    ["GetTrainerServiceDescription(1)"] = "1: string Burns the enemy for 8 Fire damage and then an additional 15 Fire damage over 15 sec.",
    ["GetTrainerServiceDescription(10)"] = "1: string Drains the soul of the target, causing 85 Shadow damage over 15 sec. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.",
    ["GetTrainerServiceDescription(100)"] = "1: string Banishes the enemy target, preventing all action but making it invulnerable for up to 30 sec.  Only one target can be banished at a time.  Only works on Demons and Elementals.",
    ["GetTrainerServiceDescription(101)"] = "1: string Ignites a target that is already afflicted by your Immolate spell, dealing 172 to 216 Fire damage and consuming your Immolate effect.",
    ["GetTrainerServiceDescription(102)"] = "1: string Creates a Greater Spellstone which can be used to enchant your weapon with Shadow, increasing your spell haste by 2% and the damage done by your Shadow spells by up to 17.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(103)"] = "1: string Instantly blasts the target for 192 to 214 Shadow damage.  If the target dies within 8 sec of Shadowburn, and yields experience or honor, the caster gains a Soul Shard.",
    ["GetTrainerServiceDescription(104)"] = "1: string Transfers 29 health from the target to the caster every 3 sec.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(105)"] = "1: string Burn the enemy's soul, causing 334 to 420 Fire damage.",
    ["GetTrainerServiceDescription(106)"] = "1: string Creates a Greater Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with 1,600 health and 2200 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(107)"] = "1: string Curses the target for 5 min, reducing Magic resistances by 75 and increasing Magic damage taken by 10%. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(108)"] = "1: string Forces the target to speak in Demonic, increasing the casting time of all spells by 60%. Only one Curse per Warlock can be active on any one target. Lasts 30 sec.",
    ["GetTrainerServiceDescription(109)"] = "1: string Causes the enemy target to run in horror for 3 sec and causes 359 Shadow damage.  The caster gains 100% of the damage caused in health.",
    ["GetTrainerServiceDescription(11)"] = "1: string Burns the enemy for 17 Fire damage and then an additional 30 Fire damage over 15 sec.",
    ["GetTrainerServiceDescription(110)"] = "1: string Protects the caster, increasing armor by 480, Shadow resistance by 12 and increases health regeneration by 13 health per 5 sec. for 30 min.",
    ["GetTrainerServiceDescription(111)"] = "1: string Allows the friendly target to detect greater invisibility for 10 min.",
    ["GetTrainerServiceDescription(112)"] = "1: string Burns the enemy for 106 Fire damage and then an additional 190 Fire damage over 15 sec.",
    ["GetTrainerServiceDescription(113)"] = "1: string Deals 134 to 156 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate.",
    ["GetTrainerServiceDescription(114)"] = "1: string Inflict searing pain on the enemy target, causing 78 to 92 Fire damage.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(115)"] = "1: string Physical damage caused by the target is reduced by 37 for 2 min. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(116)"] = "1: string Drains the soul of the target, causing 420 Shadow damage over 15 sec. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.",
    ["GetTrainerServiceDescription(117)"] = "1: string Gives 119 health to the caster's pet every second for 10 sec as long as the caster channels. Generates reduced threat.",
    ["GetTrainerServiceDescription(118)"] = "1: string Sends a shadowy bolt at the enemy, causing 180 to 202 Shadow damage.",
    ["GetTrainerServiceDescription(119)"] = "1: string Absorbs 675 shadow damage.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(12)"] = "1: string Physical damage caused by the target is reduced by 7 for 2 min. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(120)"] = "1: string Ignites a target that is already afflicted by your Immolate spell, dealing 212 to 266 Fire damage and consuming your Immolate effect.",
    ["GetTrainerServiceDescription(121)"] = "1: string Corrupts the target, causing 342 Shadow damage over 18 sec.",
    ["GetTrainerServiceDescription(122)"] = "1: string Transfers 51 health every 1 second from the target to the caster. Lasts 5 sec.",
    ["GetTrainerServiceDescription(123)"] = "1: string Transfers 136 Mana every 1 sec from the target to the caster. Lasts 5 sec.",
    ["GetTrainerServiceDescription(124)"] = "1: string Ignites the area surrounding the caster, causing 206 Fire damage to herself and 206 Fire damage to all nearby enemies every 1 sec.  Lasts 15 sec.",
    ["GetTrainerServiceDescription(125)"] = "1: string Howl, causing 5 enemies within 10 yds to flee in terror for 15 sec.  Damage caused may interrupt the effect.",
    ["GetTrainerServiceDescription(126)"] = "1: string Creates a Major Firestone which can be used to enchant your weapon with Fire, increasing your spell critical strike chance by 2% and the damage done by your Fire spells by up to 21.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(127)"] = "1: string Curses the target with recklessness, reducing the target's armor by 505 for 2 min. Cursed enemies will not flee and will ignore Fear and Horror effects. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(128)"] = "1: string Strikes fear in the enemy, causing it to run in fear for up to 20 sec.  Damage caused may interrupt the effect.  Only 1 target can be feared at a time.",
    ["GetTrainerServiceDescription(129)"] = "1: string Converts 443 Health into 443 Mana for you. Spirit increases the amount converted.",
    ["GetTrainerServiceDescription(13)"] = "1: string Gives 12 health to the caster's pet every second for 10 sec as long as the caster channels. Generates reduced threat.",
    ["GetTrainerServiceDescription(130)"] = "1: string Instantly blasts the target for 251 to 281 Shadow damage.  If the target dies within 8 sec of Shadowburn, and yields experience or honor, the caster gains a Soul Shard.",
    ["GetTrainerServiceDescription(131)"] = "1: string Burn the enemy's soul, causing 383 to 479 Fire damage.",
    ["GetTrainerServiceDescription(132)"] = "1: string Afflicts the target with agony, causing 552 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(133)"] = "1: string Creates a Major Healthstone that can be used to instantly restore 1,440 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(134)"] = "1: string Causes the enemy target to run in horror for 3 sec and causes 454 Shadow damage.  The caster gains 100% of the damage caused in health.",
    ["GetTrainerServiceDescription(135)"] = "1: string Calls down a fiery rain to burn enemies in the area of effect for 880 Fire damage over 8 sec.",
    ["GetTrainerServiceDescription(136)"] = "1: string Inflict searing pain on the enemy target, causing 105 to 123 Fire damage.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(137)"] = "1: string Transfers 41 health from the target to the caster every 3 sec.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(138)"] = "1: string Subjugates the target demon, up to level 62, forcing it to do your bidding.  While subjugated, the time between the demon's attacks is increased by 40% and its casting speed is slowed by 30%.  Lasts up to 5 min.  If you repeatedly subjugate the same demon, it will become more difficult to control with each attempt.",
    ["GetTrainerServiceDescription(139)"] = "1: string Afflicts the target with impending doom, causing 1,742 Shadow damage after 1 min.  If the target dies from this damage, there is a chance that a Doomguard will be summoned.  Cannot be cast on players. Only one Bane per Warlock can be active on any one target.\r\n",
