    ["GetTrainerServiceDescription(20)"] = "1: string Afflicts the target with agony, causing 120 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(21)"] = "1: string Creates a Minor Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with 400 health and 700 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(22)"] = "1: string Inflict searing pain on the enemy target, causing 21 to 25 Fire damage.  Causes a high amount of threat.",
    ["GetTrainerServiceDescription(23)"] = "1: string Curses the target for 5 min, reducing Magic resistances by 30 and increases Magic damage taken by 4%. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(24)"] = "1: string Protects the caster, increasing armor by 210, Shadow resistance by 3 and increases health regeneration by 7 health per 5 sec. for 30 min.",
    ["GetTrainerServiceDescription(25)"] = "1: string Gives 24 health to the caster's pet every second for 10 sec as long as the caster channels. Generates reduced threat.",
    ["GetTrainerServiceDescription(26)"] = "1: string Burns the enemy for 32 Fire damage and then an additional 60 Fire damage over 15 sec.",
    ["GetTrainerServiceDescription(27)"] = "1: string Calls down a fiery rain to burn enemies in the area of effect for 160 Fire damage over 8 sec.",
    ["GetTrainerServiceDescription(28)"] = "1: string Begins a ritual that summons the targeted group member.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.",
    ["GetTrainerServiceDescription(29)"] = "1: string Sends a shadowy bolt at the enemy, causing 54 to 62 Shadow damage.",
    ["GetTrainerServiceDescription(3)"] = "1: string Physical damage caused by the target is reduced by 4 for 2 min. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(30)"] = "1: string Creates a Lesser Healthstone that can be used to instantly restore 300 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.",
    ["GetTrainerServiceDescription(31)"] = "1: string Physical damage caused by the target is reduced by 12 for 2 min. Only one Curse per Warlock can be active on any one target.",
    ["GetTrainerServiceDescription(32)"] = "1: string Transfers 14 health every 1 second from the target to the caster. Lasts 5 sec.",
    ["GetTrainerServiceDescription(33)"] = "1: string Summons an Eye of Kilrogg and binds your vision to it.  The eye moves quickly but is very fragile.",
    ["GetTrainerServiceDescription(34)"] = "1: string Corrupts the target, causing 132 Shadow damage over 18 sec.",
    ["GetTrainerServiceDescription(35)"] = "1: string Transfers 42 Mana every 1 sec from the target to the caster. Lasts 5 sec.",
    ["GetTrainerServiceDescription(36)"] = "1: string Drains the soul of the target, causing 170 Shadow damage over 15 sec. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.",
    ["GetTrainerServiceDescription(37)"] = "1: string Shows the location of all nearby demons on the minimap until cancelled.  Only one type of tracking can be used at a time.",
    ["GetTrainerServiceDescription(38)"] = "1: string Instantly blasts the target for 75 to 85 Shadow damage.  If the target dies within 8 sec of Shadowburn, and yields experience or honor, the caster gains a Soul Shard.",
    ["GetTrainerServiceDescription(39)"] = "1: string Forces the target to speak in Demonic, increasing the casting time of all spells by 50%. Only one Curse per Warlock can be active on any one target. Lasts 30 sec.",
